#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

constexpr ll MOD = 998244353LL;
constexpr ll MODD = 1000000007LL;
constexpr int MAX_N = 1000005;
constexpr ll INF = 1000000000000000000LL;

ll p10[15];
vector<string> digit_groups[7];
vector<ll> sorted_diffs[7][7];
ll prefix_sums[7][7];

inline ll to_number(const string& s) {
    ll res = 0;
    for (char c : s) res = res * 10 + (c - '0');
    return res;
}

inline i128 compute(const string& prefix, int remaining, ll& counter) {
    if (remaining == -1) return 0;

    int L = remaining / 2;
    int R = remaining - L;
    if (remaining == 1) {
        L = 1;
        R = 0;
    }

    i128 result = (counter - to_number(prefix) + MOD * MOD) % MOD;
    counter++;

    for (const string& left : digit_groups[L]) {
        string combined = prefix + left;
        result += (-to_number(combined) + counter + MOD * MOD) % MOD;
        counter++;

        if ((int)left.size() == L) {
            ll val = to_number(combined) % MOD;
            for (int sz = 1; sz <= R; ++sz) {
                ll cst = (-val * p10[sz] + counter + MOD * MOD) % MOD;
                auto& vec = sorted_diffs[R][sz];
                int pos = lower_bound(vec.begin(), vec.end(), MOD - cst) - vec.begin();
                result += (i128)vec.size() * cst + prefix_sums[R][sz] - (i128)MOD * (vec.size() - pos);
            }
            counter += digit_groups[R].size();
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;
    string s = to_string(n);
    int N = s.size();

    p10[0] = 1;
    for (int i = 1; i <= 14; ++i) p10[i] = p10[i-1] * 10;

    for (int i = 0; i < MAX_N; ++i) {
        string num = to_string(i);
        string padded = num;
        while ((int)padded.size() <= 6) {
            padded = "0" + padded;
            digit_groups[padded.size()].push_back(padded);
        }
    }

    for (int len = 1; len <= 6; ++len) {
        for (const string& prev : digit_groups[len-1]) digit_groups[len].push_back(prev);
        sort(digit_groups[len].begin(), digit_groups[len].end());

        for (int j = 0; j < (int)digit_groups[len].size(); ++j) {
            ll val = (j - stoi(digit_groups[len][j]) + MOD) % MOD;
            sorted_diffs[len][digit_groups[len][j].size()].push_back(val);
        }

        for (int sz = 1; sz <= len; ++sz) {
            sort(sorted_diffs[len][sz].begin(), sorted_diffs[len][sz].end());
            for (ll v : sorted_diffs[len][sz]) prefix_sums[len][sz] += v;
        }
    }

    vector<pair<string, int>> queries;
    string cur = "";

    for (int i = 0; i < (int)s.size(); ++i) {
        for (int d = 0; d <= 9; ++d) {
            if (d == s[i] - '0') continue;
            if (i == 0 && d == 0) continue;

            cur += char('0' + d);
            if (d <= s[i] - '0') {
                queries.emplace_back(cur, (int)s.size() - i - 1);
            } else {
                queries.emplace_back(cur, (int)s.size() - i - 2);
            }
            cur.pop_back();
        }
        cur += s[i];
        queries.emplace_back(cur, 0);
    }

    ll counter = 1;
    i128 ans = 0;
    sort(queries.begin(), queries.end());

    for (const auto& q : queries) {
        if (s[q.first.size() - 1] == q.first.back()) {
            ans += (-to_number(q.first) + counter + MOD * MOD) % MOD;
            counter++;
            continue;
        }
        ans += compute(q.first, q.second, counter);
    }

    ans %= MODD;
    cout << (ll)ans << '\n';

    return 0;
}
